 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    marked = [[False] * w for _ in range(h)]
    for top in range(h):
        for left in range(w):
            color = grid[top][left]
            max_width = w - left
            for bottom in range(top, h):
                run = 0
                while left + run < w and grid[bottom][left + run] == color:
                    run += 1
                max_width = min(max_width, run)
                if bottom - top + 1 >= 5 and max_width >= 5:
                    for r in range(top, bottom + 1):
                        for c in range(left, left + max_width):
                            marked[r][c] = True
    return [[4 if marked[r][c] else grid[r][c] for c in range(w)] for r in range(h)]
